import json,csv,re,hashlib,statistics as st,math,random
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S=list(csv.DictReader(open('data/scores.csv')))
print(len(T),len(S), hashlib.sha256(open('data/scores.csv','rb').read()).hexdigest())
td={t['rating_id']:t for t in T}
mm=[]
for s in S:
    t=td[s['rating_id']]
    fs=re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])
    if len(fs)!=1: print('multi',s['rating_id'],fs)
    v=int(fs[-1])
    for k in ['response_id','session','displayed_label']:
        if str(t[k])!=s[k]: print('meta mismatch',s['rating_id'],k)
    if v!=int(s['score']): mm.append((s['rating_id'],s['response_id'],s['displayed_label'],s['score'],v))
print(len(mm)); [print(m) for m in mm]
def eff(get):
    d={}
    for s in S: d.setdefault(s['response_id'],{})[s['displayed_label']]=get(s)
    diffs=[v['atlas-7']-v['nova-3'] for v in d.values()]
    n=len(diffs);m=st.mean(diffs);sd=st.stdev(diffs)
    random.seed(0);cnt=0
    for _ in range(20000):
        if abs(st.mean([x*random.choice([1,-1]) for x in diffs]))>=abs(m)-1e-12: cnt+=1
    return n,m,sd,sd/math.sqrt(n),sum(x>0 for x in diffs),sum(x<0 for x in diffs),cnt/20000
print('sheet',eff(lambda s:int(s['score'])))
print('transcript',eff(lambda s:int(re.findall(r'FINAL SCORE:\s*(\d+)',td[s['rating_id']]['judge_output'])[-1])))
# session effect on transcript
tr=lambda s:int(re.findall(r'FINAL SCORE:\s*(\d+)',td[s['rating_id']]['judge_output'])[-1])
for lab in ['atlas-7','nova-3']:
  for ses in '12':
    v=[tr(s) for s in S if s['displayed_label']==lab and s['session']==ses]; print(lab,ses,len(v),st.mean(v))
